private static void writeUTF8(CharSequence str, int start, WriteSession session, LinkedBuffer lb) {
    final int length = str.length();
    int count = 0;
    for (int i = 0; i < length; i++) {
        final int codepoint = str.codePointAt(i);
        int size = 0;
        if (codepoint <= 0x7F) {
            size = 1;
        } else if (codepoint <= 0x7FF) {
            size = 2;
        } else if (codepoint <= 0xFFFF) {
            size = 3;
        } else {
            size = 4;
        }
        final int val = codepoint - (1 << (6*size));
        for (int j = start + 1 + count; j > start; --j) {
            lb.buffer().putByte(j, (byte) (val & 0x3F | 0x80));
            val >>>= 6;
        }
        lb.buffer().putByte(start + count, (byte) (0xFF >>> (8 - size)));
        count++;
    }
