* Split a box along the x axis into two equal boxes.
* 
* @param box the box to split
* @return a pair with the two resulting boxes
*/
public static Pair<Box2D,Box2D> splitAlongXAxis(Box2D box) {
    // Calculate the midpoint of the box
    double midpoint = (box.getX() + box.getWidth() / 2);

    // Create a new box with the same height as the original box, but with the left side of the original box as its left side and the midpoint as its right side
    Box2D leftBox = new Box2D(box.getY(), midpoint, box.getHeight());

    // Create a new box with the same height as the original box, but with the midpoint as its left side and the right side of the original box as its right side
    Box2D rightBox = new Box2D(box.getY(), midpoint + box.getWidth() / 2, box.getHeight());

    // Return a pair of the two resulting boxes
    return new Pair<Box2D,Box2D>(leftBox, rightBox);
}

public static Pair<Box2D, Box2D> splitAlongXAxis(Box2D box) {
    double x = box.getAX() + (box.getWidth() / 2.0);
    double y = box.getAY() + (box.getHeight() / 2.0);
    double width = box.getWidth() / 2.0;
    double height = box.getHeight() / 2.0;

    Box2D box1 = new Box2D(x, y, width, height);
    Box2D box2 = new Box2D(x + width, y, width, height);

    return new Pair<Box2D, Box2D>(box1, box2);
}

