private static boolean isPrime(int num) {
    if (num < 2) {
        return false;
    } else if (num % 2 == 0) {
        return num == 2;
    }

    int maxFactor = (int) (Math.sqrt(num) + 1);
    for (int i = 3; i <= maxFactor; i += 2) {
        if (num % i == 0) {
            return false;
        }
    }

    return true;
}

