private String unescapeId(String input) {
    // Initialize an empty string builder to store the unescaped output
    StringBuilder output = new StringBuilder();

    // Loop through each character in the input string
    for (int i = 0; i < input.length(); i++) {
        // Get the current character
        char c = input.charAt(i);

        // If the character is an escape character ('/' in this case)
        if (c == '/') {
            // Check the next character to determine the correct escape sequence
            char next = input.charAt(i + 1);
            switch (next) {
                // If the next character is 't', replace with a tab character
                case 't':
                    output.append('\t');
                    break;
                // If the next character is 'n', replace with a line feed character
                case 'n':
                    output.append('\n');
                    break;
                // If the next character is 'r', replace with a carriage return character
                case 'r':
                    output.append('\r');
                    break;
                // If the next character is '/', replace with a forward slash character
                case '/':
                    output.append('/');
                    break;
                // If the next character is any other character, replace with the next character
                default:
                    output.append(next);
                    break;
            }
            // Increment the index to skip the escaped character
            i++;
        } else {
            // If the character is not an escape character, add it to the output
            output.append(c);
        }
    }

    // Return the unescaped output
    return output.toString();
}

